export default function Footer() {
  const [copied, setCopied] = useState(false)

  function copyDiscord() {
    navigator.clipboard.writeText('magne4204').then(() => {
      setCopied(true)
      setTimeout(() => setCopied(false), 2000)
    })
  }

  return (
    <footer className="relative z-10 mt-auto border-t border-zinc-800/60 py-4 px-4">
      <div className="max-w-5xl mx-auto flex flex-col sm:flex-row items-center justify-between gap-3">

        {/* Disclaimer */}
        <p className="text-[10px] text-zinc-600 text-center sm:text-left leading-relaxed">
          ZZZendle is a fan-made project and is not affiliated with, endorsed by, or connected to HoYoverse or Zenless Zone Zero.
          All game assets belong to their respective owners.
        </p>

        {/* Links */}
        <div className="flex items-center gap-3 shrink-0">
          {/* Discord */}
          <button
            onClick={copyDiscord}
            title="Copy Discord username"
            className="flex items-center gap-1.5 text-zinc-500 hover:text-indigo-400 transition-colors text-[11px]"
          >
            <DiscordIcon />
            <span>{copied ? '✓ Copied!' : 'magne4204'}</span>
          </button>

          <span className="text-zinc-800">·</span>

          {/* Ko-fi */}
          <a
            href="https://ko-fi.com/magnen"
            target="_blank"
            rel="noopener noreferrer"
            title="Support on Ko-fi"
            className="flex items-center gap-1.5 text-zinc-500 hover:text-yellow-400 transition-colors text-[11px]"
          >
            <KofiIcon />
            <span>Ko-fi</span>
          </a>
        </div>
      </div>
    </footer>
  )
}
